<?php declare(strict_types=1);use FMonitor2\YiiRuntime\ViewSupport;use yii\helpers\Html;ViewSupport::begin($this,'Экономика объектов',$identity,'otiz','wide');$rub=static fn(?int$c)=>$c===null?'—':number_format($c/100,2,',',' ').' ₽';?>
<main class="fm2-otiz fm2-otiz-page"><header class="fm2-page-header"><div><h1>Экономика объектов</h1><p>Полный портфель, признанные обязательства и выплаты</p></div><span><?=(int)$economy['total']?> объектов</span></header><section class="fm2-otiz-register-summary"><div><span>Утверждено</span><strong><?=$rub($economy['summary']['approvedCents'])?></strong></div><div><span>Выплачено</span><strong><?=$rub($economy['summary']['paidCents'])?></strong></div><div><span>Ожидает выплаты</span><strong><?=$rub($economy['summary']['payableCents'])?></strong></div></section><form method="get" action="/pilot/otiz/objects"><label>Поиск<input class="shlz-input" name="q" value="<?=Html::encode((string)($query['q']??''))?>"></label><label>Год<select name="year"><option value="all">Все годы</option><?php foreach($economy['facets']['years']as$year):?><option<?=($query['year']??'all')===$year?' selected':''?>><?=Html::encode($year)?></option><?php endforeach?></select></label><button class="shlz-button shlz-button--primary">Показать</button></form><section class="fm2-otiz-surface"><table class="shlz-table"><thead><tr><th>Объект</th><th>Год</th><th>Фонд</th><th>Ожидает выплаты</th></tr></thead><tbody><?php foreach($economy['rows']as$row):?><tr><td><?=Html::encode($row['regnumber'])?><small><?=Html::encode($row['address'])?></small></td><td><?=Html::encode($row['year'])?></td><td><?=$rub($row['fundCents'])?></td><td><?=$rub($row['payableCents'])?><?php foreach($row['payableCalculations']as$calculation):?><a href="/pilot/otiz/calculations/<?=(int)$calculation['calculationId']?>">Расчёт #<?=(int)$calculation['calculationId']?></a><?php endforeach?></td></tr><?php endforeach?></tbody></table></section><?=ViewSupport::pagination('/pilot/otiz/objects',(int)$economy['page'],max(1,(int)ceil($economy['total']/$economy['pageSize'])),$economy['total'],$economy['pageSize'],['q'=>$query['q']??'','year'=>$query['year']??'all'],'Страницы экономики ОТиЗ')?></main><?php ViewSupport::end($this);?>
